-- the same sum the site does after each test, so lecturers see real question stats
UPDATE `Questions` SET `percentageCorrect` = COALESCE((
    SELECT ROUND(100.0 * SUM(a.isCorrect) / COUNT(*))
    FROM StudentAnswers AS sa
    INNER JOIN Answers AS a ON a.answerID = sa.selectedAnswerID
    WHERE sa.questionID = Questions.questionID
), 0)
WHERE `questionID` LIKE 'be7a0005-%';

-- the expired link for VER-05, REPLACE puts it back if a resend swapped it out
REPLACE INTO `EmailVerifications` (`userID`, `tokenHash`, `expiresAt`, `sentAt`) VALUES
  ('be7a0007-0000-4000-8000-000000000040', 'd53527fc96322216b0d7c86ed998062630db1bfb556ca278ecef64114b05033a',
    NOW() - INTERVAL 2 DAY, NOW() - INTERVAL 3 DAY);

COMMIT;
